mapper.delete:
DELETE FROM SEARCH_HISTORIES
WHERE HISTORY_ID IN (
    SELECT HISTORY_ID FROM (
                               SELECT HISTORY_ID, ROW_NUMBER() OVER (ORDER BY CREATED_AT DESC) AS RN
                               FROM SEARCH_HISTORIES
                               WHERE USER_ID = #{userId}
                           )
    WHERE RN > 2
)

DELETE FROM SEARCH_HISTORIES
WHERE USER_ID = #{userId}
AND KEYWORD = #{keyword}
